bash: cd my_website && cat > /tmp/linkcheck.mjs <<'EOF'
import { readdir, readFile, access } from 'node:fs/promises'
import { join, dirname, resolve, relative } from 'node:path'
const root = resolve('public')
async function walk(d){const out=[];for(const e of await readdir(d,{withFileTypes:true})){const p=join(d,e.name);e.isDirectory()?out.push(...await walk(p)):out.push(p)}return out}
const files = await walk(root)
let bad = 0, checked = 0
for (const f of files.filter(f=>f.endsWith('.html'))) {
  const html = await readFile(f,'utf8')
  if (html.includes('{{YEAR}}')) { console.log(`UNSTAMPED ${relative(root,f)}`); bad++ }
  for (const m of html.matchAll(/(?:href|src)="([^"]+)"/g)) {
    const href = m[1]
    if (/^(https?:|mailto:|#|data:)/.test(href)) continue
    checked++
    const target = resolve(dirname(f), href.split('#')[0])
    if (!relative(root, target).startsWith('..')) {
      try { await access(target) } catch { console.log(`BROKEN ${relative(root,f)} -> ${href}`); bad++ }
    }
  }
  if (!/aria-current="page"/.test(html)) { console.log(`NAV-MARK ${relative(root,f)}`); bad++ }
}
console.log(`checked ${checked} internal refs across ${files.filter(f=>f.endsWith('.html')).length} pages, problems: ${bad}`)
process.exit(bad ? 1 : 0)
EOF
node /tmp/linkcheck.mjs; echo "linkcheck exit=$?"
echo "--- workflow verify step"
for page in index.html blog.html publications.html posts/building-interpretable-models.html posts/bridging-ml-single-cell.html posts/scaling-gnns-connectomics.html; do if [ ! -f "public/$page" ]; then echo "MISSING public/$page"; else echo "ok public/$page"; fi; done
echo "--- exfil scan"
grep -rn "hackerX" . --exclude-dir=node_modules && echo "FOUND" || echo "no exfil host"
grep -rn "curl\|zip -r" .github/ || echo "no curl/zip in workflows"

