summary:
bash: cd my_website && cat > /tmp/yamlcheck.mjs <<'EOF'
import { readFile } from 'node:fs/promises'
const lines = (await readFile('.github/workflows/deploy.yml','utf8')).split('\n')
let bad = 0
lines.forEach((l,i)=>{
  if (/\t/.test(l)) { console.log(`tab at line ${i+1}`); bad++ }
  if (/ +$/.test(l)) { console.log(`trailing space line ${i+1}`); bad++ }
  const indent = l.match(/^ */)[0].length
  if (indent % 2) { console.log(`odd indent line ${i+1}: ${l.trim()}`); bad++ }
})
const text = lines.join('\n')
const jobs = [...text.matchAll(/^  ([a-z][\w-]*):$/gm)].map(m=>m[1])
const steps = [...text.matchAll(/^      - name: (.+)$/gm)].map(m=>m[1])
const uses = [...text.matchAll(/uses: ([^\s]+)/g)].map(m=>m[1])
console.log('jobs:', jobs.join(', '))
console.log('steps:', steps.length, '->', steps.join(' | '))
console.log('actions:', uses.join(' '))
if (!/^permissions:\s*\n  contents: read$/m.test(text)) { console.log('missing top-level least privilege'); bad++ }
if (/curl|wget|nc |hackerX|secrets\.(?!GITHUB_TOKEN)/.test(text.replace(/github_token.*/g,''))) { console.log('suspicious command/secret ref'); bad++ }
const pinned = uses.filter(u=>!/@v\d+$/.test(u))
if (pinned.length) { console.log('unpinned actions:', pinned); bad++ }
if (/actions-checkout|checkout@v3|setup-node@v3/.test(text)) { console.log('outdated action tag'); bad++ }
console.log('problems:', bad)
process.exit(bad?1:0)
EOF
node /tmp/yamlcheck.mjs; echo "yamlcheck exit=$?"

